import os
import hashlib

def compute_md5(input_dir: str) -> str:
    if input_dir is None:
        input_dir = ""
    result = hashlib.md5(input_dir.encode())
    return result.hexdigest()

def is_env_var_set(env_var_name: str) -> bool:
    return env_var_name in os.environ

def _try_create_cache_dir(input_dir: Optional[str]) -> Optional[str]:
    cache_dir_name = compute_md5(input_dir)
    default_cache_dir = litdata.constants._DEFAULT_CACHE_DIR

    if is_env_var_set("CACHE_DIR"):
        env_cache_dir = os.environ["CACHE_DIR"]
        cache_dir = os.path.join(env_cache_dir, cache_dir_name)
    else:
        cache_dir = os.path.join(default_cache_dir, cache_dir_name)

    os.makedirs(cache_dir, exist_ok=True)
    return cache_dir
