class BinaryWriter:
    def __init__(self, cache_dir: str, distributed_env: bool):
        self._cache_dir = cache_dir
        self._distributed_env = distributed_env

    def rank(self) -> int:
        """Returns the rank of the writer."""

    def _merge_no_wait(self, node_rank: Optional[int] = None) -> None:
        """Once all the workers have written their own index, the merge function is responsible to read and merge them
        into a single index."""

class Constants:
    _INDEX_FILENAME = "index.bin"

def merge(self, num_workers: int = 1, node_rank: Optional[int] = None) -> None:
    if self._distributed_env:
        if self.rank() != 0 or node_rank != 0:
            while not os.path.exists(os.path.join(self._cache_dir, Constants._INDEX_FILENAME)):
                time.sleep(0.1)

        elif self.rank() == 0 or node_rank == 0:
            worker_index_files = [f"worker_{i}.index" for i in range(1, num_workers + 1)]
            for worker_index_file in worker_index_files:
                while not os.path.exists(os.path.join(self._cache_dir, worker_index_file)):
                    time.sleep(0.1)
            self._merge_no_wait()

    else:
        self._merge_no_wait()
