from geopoly import compute_sq_dist, tesselate_geodesic

def generate_basis(
    base_shape, angular_tesselation, remove_symmetries=True, eps=1e-4
):

  if base_shape not in ['tetrahedron', 'icosahedron', 'octahedron']:
    raise ValueError('Invalid base shape')

  vertices, faces = get_polyhedron_vertices_and_faces(base_shape)

  tesselated_vertices = tesselate_geodesic(vertices, angular_tesselation, faces)

  if remove_symmetries:
    unique_vertices = []
    for v in tesselated_vertices:
      unique = True
      for u in unique_vertices:
        if compute_sq_dist(v, u) < eps:
          unique = False
          break
      if unique:
        unique_vertices.append(v)
    tesselated_vertices = np.array(unique_vertices)

  return tesselated_vertices

